// Ported from the Node app's Sequelize model RecordExtra (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class RecordExtraConfiguration : IEntityTypeConfiguration<RecordExtra>
{
    public void Configure(EntityTypeBuilder<RecordExtra> builder)
    {
        builder.ToTable("record_extras");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Entity).HasColumnName("entity").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired();
        builder.Property(e => e.EntityId).HasColumnName("entity_id");
        builder.Property(e => e.Data).HasColumnName("data").HasColumnType("nvarchar(max)").IsRequired();
        builder.HasIndex(e => new { e.Entity, e.EntityId }).IsUnique().HasDatabaseName("uq_record_extras");
    }
}
